from engine import span
def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='El reinado de Isabel de Castilla y Fernando de Aragón es el puente entre la Edad Media y la Edad Moderna en la historiografía española. Este capítulo explica cómo se unieron las dos coronas sin fundirse, cómo terminó la Reconquista con la guerra de Granada, qué sucedió en 1492 con los judíos y con Colón, y cómo se repartió el Atlántico con Portugal. La cronología del reinado figura en la {{fig:reyes-cronologia}}.',
        quotes=[Q('es_reyes','La historiografía española considera el reinado de los Reyes Católicos como la transición de la Edad Media a la Edad Moderna.'), Q('en_catolicos','whose marriage and joint rule marked the de facto unification of Spain')]))
    P.append(dict(text='Isabel y Fernando se casaron en Valladolid el 19 de octubre de 1469, con dieciocho y diecisiete años respectivamente, y eran primos segundos, de modo que necesitaron una dispensa papal para casarse. El matrimonio implicó la unión dinástica de dos coronas, no la creación de un estado único: Castilla y Aragón siguieron siendo reinos distintos hasta los decretos de Nueva Planta de 1707-1716, que se estudian en el último capítulo de este libro.',
        quotes=[Q('en_catolicos','They married on October 19, 1469, in the city of Valladolid; Isabella was 18 years old and Ferdinand a year younger.'), Q('en_catolicos','Castile and Aragon remained separate kingdoms until the Nueva Planta decrees of 1707–1716'), Q('es_reyes','cuyo matrimonio implicó la unión dinástica de sus reinos y marcó el inicio de la formación territorial de España')]))
    P.append(dict(text='Isabel accedió al trono de Castilla en 1474, al proclamarse reina tras la muerte de su hermano Enrique IV, y eso provocó una guerra de sucesión entre 1475 y 1479 contra los partidarios de Juana, hija del rey. En 1479 Fernando heredó la corona de Aragón al morir su padre. Isabel y Fernando reinaron juntos hasta la muerte de ella en 1504, y Fernando conservó después el control de Castilla como regente de su hija Juana hasta su propia muerte en 1516.',
        quotes=[Q('es_reyes','Isabel accedió al trono castellano en 1474','(1475-1479)'), Q('en_catolicos','This dispute between rival claimants led to the War of the Castilian Succession from 1475–79.'), Q('es_reyes','En 1479 Fernando heredó el trono de Aragón al morir su padre, el rey Juan II de Aragón.')]))
    P.append(dict(text='Las fuentes discrepan sobre cuándo recibieron el título de Reyes Católicos. Una dice que el papa Alejandro VI se lo concedió en 1494; otra sostiene que la bula Si convenit se expidió el 19 de diciembre de 1496, y una tercera coincide con 1496. La fecha detallada, con el día y el nombre de la bula, es más verificable que la fecha suelta, y por eso este libro usa 1496 y señala que una fuente propone 1494, quizá porque ese año el nuncio ya había aconsejado al papa aceptar la petición de dar a los reyes el título de Muy Católicos.',
        quotes=[Q('en_catolicos','was officially bestowed on Ferdinand and Isabella by Pope Alexander VI in 1494'), Q('es_reyes','la bula Si convenit, expedida el 19 de diciembre de 1496'), Q('es_granada','el papa Alejandro VI concediese a Isabel y Fernando el título de Reyes Católicos en 1496')]))
    P.append(dict(text='La guerra de Granada fue el conjunto de campañas que, entre 1482 y 1492, enfrentaron a los Reyes Católicos con el reino nazarí de Granada. Los diez años de guerra no fueron un esfuerzo continuo, sino una sucesión de campañas que empezaban en primavera y se detenían en invierno. Pesaron en el resultado las divisiones internas del bando musulmán y el uso eficaz de la artillería, que permitió tomar rápidamente plazas que de otro modo habrían exigido largos asedios. La mayor parte de las tropas y del dinero salió de Castilla; Aragón, aparte de la presencia del propio Fernando, aportó apoyo naval, artilleros y préstamos.',
        quotes=[Q('es_granada','La guerra de Granada fue el conjunto de campañas militares que tuvieron lugar entre 1482 y 1492'), Q('en_granada','The ten-year war was not a continuous effort but a series of seasonal campaigns launched in spring and broken off in winter.'), Q('en_granada','The war saw the effective use of artillery by the Christians to rapidly conquer towns that would otherwise have required long sieges.'), Q('es_granada','La participación de la Corona de Aragón fue de menor importancia','la aportación de expertos artilleros y el empréstito financiero')]))
    P.append(dict(text='El 2 de enero de 1492 el sultán Boabdil entregó Granada y la Alhambra ({{fig:rendicion-granada}}), y con ello terminó el último reino musulmán de la península. La guerra se considera en la historiografía tradicional la última de la Reconquista, aunque también se ha dicho que fue una de las primeras guerras de la Edad Moderna por el papel de los asedios resueltos con artillería. Las consecuencias fueron religiosas: según una de las fuentes, los judíos tuvieron que convertirse o exiliarse en 1492 y, en 1501, los musulmanes de Granada tuvieron que convertirse, ser esclavizados o exiliarse.',
        quotes=[Q('en_granada','On 2 January 1492, Muhammad XI of Granada (King Boabdil) surrendered the Emirate of Granada, the city of Granada, and the Alhambra palace to the Castilian forces.'), Q('es_granada','fue una de las primeras guerras de la Edad Moderna'), Q('en_granada','Jews were forced to convert to Christianity or be exiled in 1492, and by 1501, all of Granada\'s Muslims were obliged to convert to Christianity, become slaves, or be exiled')]))
    P.append(dict(text='El 31 de marzo de 1492, en la Alhambra, los Reyes Católicos promulgaron el edicto que ordenaba la expulsión de los judíos no convertidos de las coronas de Castilla y de Aragón; el plazo final era el 31 de julio, aunque por motivos logísticos se amplió al 2 de agosto. Las cifras son objeto de debate. De unos 300 000 judíos, entre 40 000 y 100 000 habrían sido expulsados, pero las dos fuentes difieren en cuántos se convirtieron: entre 100 000 y 200 000 según una, más de 200 000 según la otra. Por eso conviene dar un intervalo y no una cifra única.',
        quotes=[Q('es_edicto','dos decretos promulgados el 31 de marzo de 1492 en la Alhambra'), Q('es_edicto','de unos 300 000 judíos que vivían en España, entre 100 000 y 200 000 se convirtieron para evitar la expulsión','entre 40 000 y 100 000 resultaron desahuciados de la península'), Q('en_alhambra','a total of over 200,000 had converted to Catholicism in order to remain in Spain, and between 40,000 and 100,000 remained Jewish and suffered expulsion')]))
    P.append(dict(text='La Inquisición se fundó en 1478 por iniciativa de los Reyes Católicos, bajo control directo de la Corona, para mantener la ortodoxia católica. Los primeros inquisidores se nombraron en 1480. Se estima que procesó a unas 150 000 personas, de las que entre 3000 y 5000 fueron entregadas al Estado para su ejecución, sobre todo en los primeros cincuenta años. Su blanco inicial fueron los conversos sospechosos de seguir practicando el judaísmo o el islam en secreto. La Inquisición fue, según Henry Kamen, la única institución cuya autoridad abarcaba todos los reinos de España.',
        quotes=[Q('es_inquisicion','una institución fundada en 1478 por los Reyes Católicos que, bajo el control directo de la Corona'), Q('en_inquisition','the Inquisition prosecuted an estimated 150,000 people for various offences'), Q('es_reyes','«la única institución cuya autoridad abarcaba todos los reinos de España»'), Q('en_inquisition','the first inquisitors, Miguel de Morillo and Juan de San Martín, were appointed by the future Catholic Monarchs, King Ferdinand II of Aragon and Queen Isabella I of Castile, in 1480')]))
    P.append(dict(text='La corona respaldó el proyecto de Colón siete años después de rechazarlo, una vez terminada la conquista de Granada. Las Capitulaciones de Santa Fe, firmadas cerca de Granada el 17 de abril de 1492, nombraban a Colón almirante, virrey y gobernador general de las tierras que descubriera. El texto original de las Capitulaciones lo dice con otras palabras: los reyes hacen a Colón «su almirante» y «su visorey e gouernador general», y le conceden «la dezena parte» de las mercancías, «quedando las otras nueve partes» para los reyes, descontados los gastos.',
        quotes=[Q('es_reyes','Cerca de Granada se firmaron el 17 de abril de 1492 las Capitulaciones de Santa Fe por las que Colón era nombrado almirante, virrey y gobernador general de las tierras que descubriera.'), Q('ws_capitulaciones','fazen dende agora al dicho don Christoual Colon su almirante'), Q('ws_capitulaciones','la dezena parte de todo ello quitadas las costas todas','quedando las otras nueve partes para vuestras altezas')]))
    P.append(dict(text='En el regreso de su primer viaje, en 1493, Colón hizo escala en Lisboa, y el rey de Portugal escribió a los Reyes Católicos que, por el Tratado de Alcáçovas de 1479 y por una bula papal de 1481, las tierras descubiertas eran portuguesas. La disputa se resolvió con el Tratado de Tordesillas, firmado el 7 de junio de 1494, que trazó una línea de demarcación a 370 leguas al oeste de las islas de Cabo Verde: lo que quedara al este pertenecería a Portugal y lo que quedara al oeste, a Castilla. Las dos fuentes expresan la distancia en kilómetros con valores distintos, unos 2062 km y unos 2100 km, que dependen de la longitud de legua que se adopte.',
        quotes=[Q('es_tordesillas','una línea situada a 370 leguas (unos 2062 km) al oeste de las islas de Cabo Verde'), Q('en_tordesillas','along a meridian 370 leagues (c. 2,100 km or 1,300 mi) west of the Cape Verde islands'), Q('en_tordesillas','The lands to the east would belong to Portugal and the lands to the west to Castile'), Q('en_tordesillas','On his way back to Spain, he first stopped at Lisbon'), Q('en_tordesillas','by the Treaty of Alcáçovas signed in 1479 and by the 1481 papal bull Aeterni regis that granted all lands south of the Canary Islands to Portugal, all of the lands discovered by Columbus belonged to Portugal')]))
    P.append(dict(role='definition', text='Unión dinástica o monarquía compuesta: unión de varios reinos bajo un mismo monarca en la que cada reino conserva sus propias leyes e instituciones. La unión de Castilla y Aragón fue de este tipo hasta los decretos de Nueva Planta.',
        quotes=[Q('es_reyes','La unión se caracterizó por ser personal, es decir, que los distintos territorios, estados y señoríos compartían monarca, pero mantenían sus leyes e instituciones propias'), Q('en_catolicos','Spain was formed as a dynastic union of two crowns rather than a unitary state')]))
    P.append(dict(role='consejo', text='Cuando dos fuentes dan fechas o cifras distintas, anótelas las dos con su procedencia y busque una tercera o el dato más detallado, como el nombre de la bula y el día. No promedie ni escoja la cifra que mejor encaje. En este capítulo ocurre con el título de Reyes Católicos (1494 o 1496) y con el número de judíos convertidos y expulsados en 1492.',
        quotes=[Q('es_reyes','la bula Si convenit, expedida el 19 de diciembre de 1496'), Q('en_alhambra','between 40,000 and 100,000 remained Jewish and suffered expulsion')]))
    P.append(dict(role='self_check', text='¿Por qué la unión de Castilla y Aragón no creó un estado único? ¿Qué sucedió en 1492 y qué relación tuvieron entre sí la toma de Granada, el edicto de los judíos y las Capitulaciones de Santa Fe? ¿Cómo explica la diferencia entre 1494 y 1496 para el título de Reyes Católicos?',
        quotes=[Q('es_granada','La protocolaria entrega de las llaves de la ciudad de Granada y la ciudad palatina de la Alhambra el 2 de enero de 1492'), Q('en_alhambra','an edict issued on 31 March 1492 by the joint Catholic Monarchs of Spain')]))
    return P

def _legacy_numeric_problems(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    return [dict(role='worked', problem_type='NUMERICAL',
        prompt='Según las Capitulaciones de Santa Fe, Colón recibe la décima parte de las mercancías ganadas en su almirantazgo, descontados los gastos, y las otras nueve partes son para los reyes. Si en una expedición hipotética el beneficio neto, una vez pagados todos los costes, fuese de 4 000 000 de maravedís, calcule cuántos maravedís corresponderían a la Corona.',
        expected='3600000', quotes=[Q('ws_capitulaciones','la dezena parte de todo ello quitadas las costas todas','quedando las otras nueve partes para vuestras altezas'), Q('es_reyes','Además se le otorgaba la décima parte de todas las riquezas que encontrara.')],
        method='Reparto proporcional de un beneficio neto',
        solution=dict(given=[dict(symbol='B',value=4000000,unit='dimensionless',meaning='beneficio neto, en maravedís (cifra hipotética)'),dict(symbol='f',value=0.1,unit='dimensionless',meaning='fracción para Colón: la décima parte')],
          unknown='La cantidad que corresponde a Colón y la que corresponde a la Corona.',
          model=[dict(name='Parte de Colón',latex='C = f\\,B',symbolic='f*B'),dict(name='Parte de la Corona',latex='R = B - C = (1-f)\\,B',symbolic='(1-f)*B')],
          assumptions=['La cifra de 4 000 000 de maravedís es hipotética y sirve solo para ilustrar la proporción.','La décima parte se calcula una vez descontados todos los gastos, como dice el texto.'],
          development=['La décima parte es una fracción de 1/10 y las otras nueve partes son las 9/10 restantes.'],
          steps=[dict(text='Parte de Colón',equation='C = 0{,}1 \\cdot 4\\,000\\,000',expression='0.1*4000000',expected=400000,unit='dimensionless'),
                 dict(text='Parte de la Corona',equation='R = 4\\,000\\,000 - 400\\,000',expression='4000000-400000',expected=3600000,unit='dimensionless')],
          result='A Colón le corresponderían 400 000 maravedís y a la Corona 3 600 000, es decir, el 90 % del beneficio neto.',
          interpretation='La proporción de nueve a uno muestra que la corona conservaba casi todo el beneficio, mientras que Colón recibía además los títulos hereditarios de almirante, virrey y gobernador.',
          limitations=['El ejemplo supone que los costes ya están descontados; en la práctica el cálculo dependía de cómo se contabilizaran.'],
          mistakes=['Aplicar la décima parte al total bruto en lugar de al beneficio una vez descontados los gastos.']))]


def extend(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(text='Cómo se repartió el poder\nLa boda de 1469 no fundió dos reinos en uno: fijó, mediante capitulaciones, quién mandaba en cada uno. En las capitulaciones de Cervera Fernando se comprometió a respetar los fueros castellanos, a no firmar nada sin la firma de Isabel y a no otorgar mercedes ni cargos, que eran prerrogativa exclusiva de la reina. Tras la muerte de Enrique IV, la Concordia de Segovia de 1475 estableció la fórmula definitiva: los documentos irían a nombre de ambos, el nombre del rey antes que el de la reina y las armas de la reina antes que las del rey. Según el historiador Joseph Pérez, en el terreno jurídico Isabel seguía siendo la única reina de Castilla, mientras que de hecho Fernando recibía amplísimos poderes.',
        quotes=[Q('es_reyes','Fernando se comprometía a respetar las libertades y los fueros de las villas y ciudades castellanas','no podría ordenar nada si su firma no iba acompañada de la de su esposa'), Q('es_reyes','las mercedes y oficios serían concesión de la reina sola'), Q('en_catolicos','Though their marriage united the two kingdoms, leading to the beginnings of modern Spain, they ruled independently')]))
    P.append(dict(text='La divisa del yugo y las flechas. Hernando del Pulgar escribió que los reyes eran «una voluntad que moraba en dos cuerpos», y por eso sus iniciales y sus empresas (el yugo de Fernando, las flechas de Isabel) aparecen en monedas, documentos y edificios. Pero las dos fuentes no cuentan lo mismo sobre el lema Tanto monta: una advierte que era un lema exclusivo de Fernando, ligado al nudo gordiano de Alejandro Magno, y otra recoge su interpretación posterior como expresión de igualdad entre los monarcas. Es un buen ejemplo de cómo un símbolo cambia de sentido con el tiempo.',
        quotes=[Q('es_reyes','una voluntad que moraba en dos cuerpos'), Q('es_reyes','era un lema exclusivo de Fernando'), Q('en_catolicos','but later adopted as an expression of equality of the monarchs')]))
    P.append(dict(text='La pacificación de Castilla\nLo primero que hicieron los reyes tras la guerra civil fue restablecer el orden. Para ello contaron con la Hermandad, fundada en abril de 1476 en las Cortes de Madrigal de las Altas Torres: cada municipio de más de doscientos habitantes pagaba un impuesto especial para sostener a dos jueces y una brigada de cuadrilleros. Era en origen una institución temporal, pero se prolongó hasta que, por el coste que suponía para los municipios, en 1498 se suprimieron los órganos centrales y solo quedaron las cuadrillas locales contra el bandidaje rural. Joseph Pérez la resume como un organismo a la vez policial y judicial, apoyo muy apreciable para unos soberanos que querían afianzar su poder.',
        quotes=[Q('es_reyes','la Hermandad, fundada en abril de 1476 en las Cortes de Castilla reunidas en Madrigal de las Altas Torres'), Q('es_reyes','Para ahorrar gastos en 1498 se suprimirán los órganos centrales'), Q('en_catolicos','These men were used as a judicial police force for Castile, as well as to attempt to keep Castilian nobles in check.')]))
    P.append(dict(role='definition', text='Santa Hermandad: cuerpo de policía y de justicia rural, pagado por los municipios, que los Reyes Católicos fundaron en 1476 para perseguir el bandidaje y reforzar la autoridad de la Corona frente a la nobleza.',
        quotes=[Q('es_reyes','Según Joseph Pérez, «la Santa Hermandad, organismo al tiempo policial y judicial'), Q('en_catolicos','they first created a group named the Santa Hermandad "Holy Brotherhood"')]))
    P.append(dict(text='Un gobierno de letrados\nEl Consejo Real, consejo privado del soberano, se reformó: lo presidía un obispo y lo integraban tres caballeros y ocho o nueve juristas, de modo que la alta nobleza, que podía seguir asistiendo como observadora, perdió todo poder efectivo y dejó de acudir. El Consejo pasó a ser el órgano supremo de gobierno, con atribuciones administrativas y también judiciales. La fuente inglesa lo describe como el órgano central de gobierno de Castilla, con funcionarios leales a los reyes y excluyendo a la vieja nobleza. Los secretarios que preparaban sus sesiones fueron ganando importancia, aunque nunca llegaron a ser verdaderos ministros.',
        quotes=[Q('es_reyes','Presidido por un obispo quedó integrado por tres caballeros','perdiendo así todo poder efectivo'), Q('en_catolicos','with wide powers and with royal officials who were loyal to them and excluded the old nobility from exercising power in it'), Q('es_reyes','aunque nunca se convertirán en verdaderos ministros')]))
    P.append(dict(text='Corregidores y ciudades. En el ámbito local extendieron con carácter permanente la institución de los corregidores a todas las ciudades. Sin su aprobación ninguna decisión del concejo municipal tenía validez, y el reino quedó dividido en sesenta y cuatro corregimientos. Se escogían entre juristas universitarios (letrados) o entre la pequeña nobleza, su mandato duraba generalmente dos años y al terminarlo se sometían a un juicio de residencia. Para Joseph Pérez fueron los agentes más eficaces de la Corona para restablecer la autoridad del Estado. La fuente inglesa lo ve como el nombramiento de magistrados para gobernar villas y ciudades, parte de lo que llama la «pacificación de Castilla».',
        quotes=[Q('es_reyes','extendieron la institución de los corregidores con carácter permanente a todas las ciudades'), Q('es_reyes','cuando acababa su ejercicio, generalmente de dos años, su gestión era sometida a un juicio de residencia'), Q('en_catolicos','appointed magistrates to run the towns and cities')]))
    P.append(dict(role='definition', text='Corregidor: delegado de la Corona en una ciudad y su territorio, con poderes amplios sobre el concejo; su gestión se sometía a un juicio de residencia al terminar su mandato.',
        quotes=[Q('es_reyes','Por otro lado, cuando acababa su ejercicio'), Q('en_catolicos','appointed magistrates to run the towns and cities')]))
    P.append(dict(text='Las Cortes, convocadas lo menos posible. Los reyes recurrieron al principio a las Cortes para respaldar su política (Madrigal en 1476, Toledo en 1479-1480), pero después pasaron casi veinte años sin reunirlas. Pérez lo explica porque las contribuciones indirectas, como las alcabalas y las bulas de la Cruzada, aseguraban ingresos regulares sin necesidad del impuesto directo que exigía el consentimiento de las Cortes. Además los corregidores fiscalizaban la elección de los procuradores. La fuente inglesa coincide en que Isabel buscó diversos medios para reducir la influencia de las Cortes de Castilla, algo que Fernando no hizo en Aragón.',
        quotes=[Q('es_reyes','pasaron casi veinte años sin celebrar ninguna'), Q('es_reyes','las contribuciones indirectas (alcabalas, impuestos de consumo; bulas de la Cruzada, cobradas por el Estado) aseguran beneficios regulares y sustanciosos a la Corona'), Q('en_catolicos','Isabella also sought various ways to diminish the influence of the Cortes Generales in Castile')]))
    P.append(dict(text='La nobleza, domesticada pero no derribada. El primer objetivo fue recuperar las rentas, impuestos y tierras que la nobleza había arrebatado a la Corona durante la crisis sucesoria iniciada en 1464, lo que saneaba la Hacienda y reducía su poder. Según Pérez, esto no significaba derribar a la alta nobleza, sino quitarle toda influencia política, reforzando una red de agentes ajenos a ella y privándola del voto en el Consejo Real. Es decir, se buscaba una monarquía más fuerte sin ruptura con la aristocracia.',
        quotes=[Q('es_reyes','el primer objetivo fue rescatar rentas (juros), impuestos, tierras, beneficios eclesiásticos, etc. que había arrebatado a la Corona'), Q('es_reyes','quitarle «toda influencia política, al reforzar su red de agentes (corregidores), escogidos fuera de ella, y al privarla del derecho de voto en el Consejo Real»'), Q('en_catolicos','The Catholic Monarchs set out to restore royal authority in Spain.')]))
    P.append(dict(text='Aragón: la unión sin uniformidad\nLa Corona de Aragón conservó las leyes e instituciones propias de cada uno de sus reinos. Se introdujeron tres novedades: el Consejo de Aragón, creado en 1494 como parte del Consejo Real; el sistema virreinal, necesario por las largas ausencias de Fernando, y las Reales Audiencias de cada estado, a las que se suma la Inquisición. Ernest Belenguer advierte que Fernando no pudo actuar con la misma unidad en todos sus reinos: tuvo escaso margen en Aragón y más posibilidades en Cataluña. La fuente inglesa subraya que, incluso después de la unión de coronas bajo un monarca, las Cortes aragonesas, catalanas y valencianas conservaron un poder significativo.',
        quotes=[Q('es_reyes','el Consejo de Aragón (creado en 1494 como parte del Consejo Real), la proliferación del sistema virreinal'), Q('es_reyes','pequeños márgenes de intervención que le obligaron a la inhibición en Aragón'), Q('en_catolicos','the Aragonese, Catalan, and Valencian Corts (parliaments) retained significant power in their respective regions')]))
    P.append(dict(text='El campo catalán y la Sentencia de Guadalupe. En Cataluña la guerra remensa enfrentó a campesinos y señores por los llamados «malos usos». Fernando adoptó una solución de compromiso, la Sentencia Arbitral de Guadalupe de 1486, por la que los malos usos se redimían pagando sesenta sueldos por mas y los campesinos obtenían ciertas libertades. En Aragón, en cambio, la Sentencia de Ariza de 1497 confirmó los derechos señoriales: la potestad de la nobleza aragonesa sobre sus campesinos permaneció intacta. La comparación de ambos territorios muestra que la misma Corona obtuvo resultados distintos según la fuerza de las élites de cada reino.',
        quotes=[Q('es_reyes','los malos usos eran redimidos mediante el pago de sesenta sueldos por mas y los campesinos conseguían una serie de libertades'), Q('es_reyes','Sentencia de Ariza de 1497 en la que Fernando el Católico confirmó los derechos señoriales'), Q('en_catolicos','their kingdoms retained part of their own regional laws and governments for the next two centuries')]))
    P.append(dict(text='Un ejército permanente\nLa Corona convirtió el ejército en una fuerza permanente, sobre todo a partir de 1495, cuando comienzan las campañas de Italia en las que destacó Gonzalo Fernández de Córdoba, el Gran Capitán. La fuente inglesa precisa que reorganizó las tropas en una nueva unidad, los tercios, el primer ejército moderno dependiente de la Corona con independencia de las pretensiones de los nobles; en rigor, el Gran Capitán creó las coronelías (1503) y los tercios se constituyeron bajo Carlos I, hacia 1534-1536. El cambio importa porque la fuerza militar dejaba de ser asunto de las mesnadas señoriales y pasaba a ser un instrumento del rey.',
        quotes=[Q('es_reyes','la conversión del ejército en una fuerza permanente (especialmente a partir de 1495'), Q('en_catolicos','which entailed the creation of the first modern army dependent on the crown, regardless of the pretensions of the nobles')]))
    P.append(dict(text='Una política de alianzas\nCasar a los hijos como política exterior: los reyes buscaron para sus cinco hijos matrimonios que sirvieran a largo plazo a la monarquía: Isabel y María con Portugal, Juana con Felipe el Hermoso, hijo del emperador Maximiliano, Juan con Margarita de Austria y Catalina con el heredero de Inglaterra. La estrategia no salió como se esperaba: el único hijo varón, Juan, murió joven, Catalina fue repudiada por Enrique VIII y Felipe murió pronto, dejando a una Juana considerada incapaz de gobernar. Esos accidentes dinásticos explican que la herencia acabara en manos de su nieto Carlos.',
        quotes=[Q('en_catolicos','The matrimonial policy of the monarchs sought advantageous marriages for their five children'), Q('en_catolicos','These alliances were not all long-lasting, with their only son and heir-apparent John dying young'), Q('ws_testamento','instituyo por universal heredera de todos mis Reynos')]))
    P.append(dict(text='El testamento de Isabel\nEl 12 de octubre de 1504, en Medina del Campo, Isabel dictó su testamento. Ordenó ser enterrada en el monasterio de San Francisco de la Alhambra, en una sepultura baja y sin bulto, y nombró heredera universal de sus reinos a su hija Juana, a quien mandó titularse reina de inmediato. El texto contiene además cláusulas de gobierno muy reveladoras: prohíbe dar cargos, fortalezas y oficios a quienes no sean naturales de los reinos, porque por ser de otra nación y lengua el príncipe Felipe podría no ser obedecido, y reserva el comercio de las Indias a Castilla. Es una fuente primaria que permite ver cómo concebía Isabel su reino.',
        quotes=[Q('ws_testamento','hecho en la villa de Medina del Campo, a doce de octubre del año 1504'), Q('ws_testamento','una sepultura baxa que no tenga bulto aguno'), Q('ws_testamento','a la Ilustrísima Princesa Doña Juana, Archiduquesa de Austria'), Q('en_catolicos','The Catholic Monarchs\' daughter Joanna succeeded to the crown of Castile, but was deemed unfit to rule.')]))
    P.append(dict(text='Las Indias en el testamento. Una cláusula del testamento ordena que los indios vecinos y moradores de las Indias y Tierra Firme no reciban agravio alguno en sus personas ni bienes, y que sean tratados bien y justamente; si lo han recibido, deben repararlo. Es una cláusula conocida, pero conviene leerla con cuidado: expresa una obligación moral de la Corona dentro del marco de la concesión pontificia de las Indias, y no es una abolición de la conquista ni de la dependencia de los indígenas. Otra cláusula reserva el trato y provecho de las Indias a los reinos de Castilla y de León, porque fueron descubiertas y conquistadas a su costa y con sus naturales.',
        quotes=[Q('ws_testamento','non consientan e den lugar que los indios vezinos e moradores en las dichas Indias e tierra firme, ganadas e por ganar, reciban agravio alguno en sus personas e bienes'), Q('ws_testamento','el trato e provecho dellas se aya e trate e negocie destos mis Reynos de Castilla y de León'), Q('en_catolicos','Through the Capitulations of Santa Fe, navigator Christopher Columbus received finances')]))
    P.append(dict(text='¿Nació entonces el Estado-nación español?\nLa historiografía discute si el reinado de los Reyes Católicos fue el nacimiento de España como nación ({{fig:doble-monarquia}}). Domínguez Ortiz subraya que la unión política fue «mucho menos sólida de lo que suele pensarse»: ninguna institución propia fue modificada, había aduanas en la frontera, la moneda y las leyes eran distintas y la única institución común fue la Inquisición. Joseph Pérez va más lejos: es «un error que conviene desterrar» decir que fundaron la unidad nacional y prefiere hablar de «doble monarquía». Ladero Quesada concluye que empezó el Estado moderno, pero no un Estado nacional unitario, y que solo comenzaba «un largo y laborioso proceso». La fuente inglesa recuerda que Castilla y Aragón siguieron siendo reinos separados hasta los decretos de Nueva Planta.',
        quotes=[Q('es_reyes','dicha unión política fue algo mucho menos sólido de lo que suele pensarse'), Q('es_reyes','es un error que conviene desterrar'), Q('es_reyes','En suma, a finales del siglo XV comenzaba solamente un largo y laborioso proceso'), Q('en_catolicos','Castile and Aragon remained separate kingdoms until the Nueva Planta decrees of 1707–1716')]))
    return P


